describe('Reduced Motion Preference', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should disable reduced motion animations when prefers-reduced-motion is set to true', () => {
    // Set prefers-reduced-motion to true
    cy.viewport('iphone-x');
    cy.get('[data-testid="body"]').then(($body) => {
      cy.wrap($body).invoke('attr', 'style', 'prefers-reduced-motion: reduce;');
    });

    // Verify reduced motion is active
    cy.get('[data-testid="modal-enter-animation"]').should('not.exist');
    cy.get('[data-testid="page-transition-animation"]').should('not.exist');

    // Verify content is still accessible
    cy.get('[data-testid="modal-content"]').should('be.visible');
    cy.get('[data-testid="modal-title"]').should('contain', 'Modal Title');

    // Verify no jarring animations are present
    cy.get('[data-testid="modal-content"]').should('have.css', 'transform', 'none');
    cy.get('[data-testid="modal-content"]').should('have.css', 'opacity', '1');

    // Verify modal can still be interacted with
    cy.get('[data-testid="modal-close-button"]').click();
    cy.get('[data-testid="modal-content"]').should('not.exist');
  });

  it('should enable reduced motion animations when prefers-reduced-motion is not set', () => {
    // Remove reduced motion style
    cy.get('[data-testid="body"]').then(($body) => {
      cy.wrap($body).invoke('removeAttr', 'style', 'prefers-reduced-motion');
    });

    // Verify reduced motion animations are enabled
    cy.get('[data-testid="modal-enter-animation"]').should('be.visible');
    cy.get('[data-testid="page-transition-animation"]').should('be.visible');

    // Verify animations are applied
    cy.get('[data-testid="modal-content"]').should('have.css', 'transform', 'translateY(0px)');
    cy.get('[data-testid="modal-content"]').should('have.css', 'opacity', '0');

    // Verify modal can still be interacted with
    cy.get('[data-testid="modal-close-button"]').click();
    cy.get('[data-testid="modal-content"]').should('not.exist');
  });
});
